SELECT tr.id AS run_id, t.train_no, t.train_type, origin_station.name AS origin_station, terminal_station.name AS terminal_station, from_station.name AS from_station, to_station.name AS to_station, fs.stop_seq AS from_seq, ts.stop_seq AS to_seq, TIMESTAMP(DATE_ADD(tr.run_date, INTERVAL fs.departure_day_offset DAY), fs.departure_time) AS departure_date_time, TIMESTAMP(DATE_ADD(tr.run_date, INTERVAL ts.arrival_day_offset DAY), ts.arrival_time) AS arrival_date_time, TIMESTAMPDIFF(MINUTE, TIMESTAMP(DATE_ADD(tr.run_date, INTERVAL fs.departure_day_offset DAY), fs.departure_time), TIMESTAMP(DATE_ADD(tr.run_date, INTERVAL ts.arrival_day_offset DAY), ts.arrival_time)) AS duration_minutes FROM train_run tr JOIN train t ON t.id = tr.train_id JOIN train_stop fs ON fs.train_id = t.id AND fs.station_id = #{query.fromStationId} JOIN train_stop ts ON ts.train_id = t.id AND ts.station_id = #{query.toStationId} AND ts.stop_seq > fs.stop_seq JOIN station from_station ON from_station.id = fs.station_id JOIN station to_station ON to_station.id = ts.station_id JOIN train_stop origin_stop ON origin_stop.train_id = t.id AND origin_stop.stop_seq = 1 JOIN station origin_station ON origin_station.id = origin_stop.station_id JOIN train_stop terminal_stop ON terminal_stop.train_id = t.id AND terminal_stop.stop_seq = (SELECT MAX(x.stop_seq) FROM train_stop x WHERE x.train_id = t.id) JOIN station terminal_station ON terminal_station.id = terminal_stop.station_id WHERE tr.run_date = #{query.travelDate} AND tr.sale_status = 'ON_SALE' AND tr.inventory_initialized = 1 AND t.status = 'ACTIVE'
AND t.train_type IN
#{trainType}
AND fs.departure_time >= #{query.departureTimeStart}
AND fs.departure_time <= #{query.departureTimeEnd}
ORDER BY departure_date_time DESC ORDER BY duration_minutes ASC, departure_date_time ASC ORDER BY departure_date_time ASC

SELECT tr.id AS run_id, tr.train_id, t.train_no, tr.sale_status, tr.inventory_initialized,
fs.station_id AS from_station_id, ts.station_id AS to_station_id,
fs.stop_seq AS from_seq, ts.stop_seq AS to_seq
FROM train_run tr
JOIN train t ON t.id = tr.train_id
JOIN train_stop fs ON fs.train_id = tr.train_id AND fs.station_id = #{fromStationId}
JOIN train_stop ts ON ts.train_id = tr.train_id AND ts.station_id = #{toStationId}
AND ts.stop_seq > fs.stop_seq
WHERE tr.id = #{runId}
LIMIT 1

SELECT price FROM train_fare
WHERE train_id = #{trainId} AND from_seq = #{fromSeq} AND to_seq = #{toSeq}
AND seat_type_id = #{seatTypeId}
LIMIT 1
